const search=document.getElementById('place-search');function filter(){let count=0;document.querySelectorAll('.place-group').forEach(group=>{let visible=0;group.querySelectorAll('li').forEach(li=>{li.hidden=!li.textContent.toLowerCase().includes(search.value.toLowerCase().trim());if(!li.hidden)visible++});group.hidden=visible===0;count+=visible});document.getElementById('place-count').textContent=count?(count+' places to revisit.'):'No places match. Try another name.'}search.addEventListener('input',filter);filter();